{"operationName":"contentCmsPage","variables":{"path":"/bonus","cmsMode":"DEFAULT","options":{"viewDate":"2026-05-12","maxComponentsToFullyReturn":20}},"extensions":{"clientLibrary":{"name":"@apollo/client","version":"4.2.0-alpha.1"}},"query":"query contentCmsPage($path: String!, $options: ContentPageOptions, $cmsMode: CmsMode) {
