            entries {
              href
              images {
                description
                variants {
                  url
                  width
                  height
                  variant
                  __typename
                }
                __typename
              }
              stickerImages {
                description
                variants {
                  url
                  width
                  height
                  variant
                  __typename
                }
                __typename
              }
              subtitle
              theme
              title
              titleAnalytics
              documentUUID
              campaignTag
              __typename
            }
            seeMoreLink {
              theme
              href
              target
              title
              mobileLink
              isExternalMobileLink
              __typename
            }
            title
            meta {
              promoModel
              promoOrchestrator
              promoIsManual
              __typename
            }
            type
            __typename
          }
          __typename
        }
        ... on ContentAdvertorial {
          anchorId
          id
          tagLevel
          componentStatus
          type
          data {
            advertorials {
              title
              link {
                href
                theme
                title
                target
                __typename
              }
              textColor
              backgroundColor
              images {
                url
                width
                height
                variant
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}"}

